package vn.edu.eaut.lab6.controller; import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import vn.edu.eaut.lab6.model.Student;import vn.edu.eaut.lab6.store.StudentStore;import java.io.*;
@WebServlet("/students") public class StudentServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{String k=q.getParameter("keyword");q.setAttribute("students",k==null?StudentStore.findAll():StudentStore.search(k));q.setAttribute("keyword",k==null?"":k);q.getRequestDispatcher("/student-list.jsp").forward(q,p);} protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{q.setCharacterEncoding("UTF-8");String id=q.getParameter("id"),name=q.getParameter("name"),cl=q.getParameter("className"),email=q.getParameter("email");if(blank(id)||blank(name)||blank(cl)||blank(email)){p.sendRedirect(q.getContextPath()+"/student-form.jsp?error=empty");return;}if(StudentStore.findById(id)!=null){p.sendRedirect(q.getContextPath()+"/student-form.jsp?error=duplicate");return;}StudentStore.add(new Student(id.trim(),name.trim(),cl.trim(),email.trim()));p.sendRedirect(q.getContextPath()+"/students");}private boolean blank(String s){return s==null||s.trim().isEmpty();}}
